class Solution {
    public int findKthNumber(int n, int k) {
        long current = 1;
        long remaining = k - 1L;
        while (remaining > 0) {
            long steps = countSteps(n, current);
            if (steps <= remaining) {
                current++;
                remaining -= steps;
            } else {
                current *= 10;
                remaining--;
            }
        }
        return (int) current;
    }

    private long countSteps(int n, long prefix) {
        long first = prefix;
        long next = prefix + 1;
        long steps = 0;
        while (first <= n) {
            steps += Math.min(n + 1L, next) - first;
            first *= 10;
            next *= 10;
        }
        return steps;
    }
}

class Solution {
    public int findKthNumber(int n, int k) {
        long prefix = 1;
        long rank = k - 1L;
        while (rank > 0) {
            long subtree = countInclusiveRange(n, prefix);
            if (subtree <= rank) {
                prefix++;
                rank -= subtree;
            } else {
                prefix *= 10;
                rank--;
            }
        }
        return (int) prefix;
    }

    private long countInclusiveRange(int n, long prefix) {
        long first = prefix;
        long last = prefix;
        long count = 0;
        while (first <= n) {
            count += Math.min((long) n, last) - first + 1;
            first *= 10;
            last = last * 10 + 9;
        }
        return count;
    }
}

class Solution {
    public int findKthNumber(int n, int k) {
        long remaining = k;
        for (int root = 1; root <= 9; root++) {
            long count = countPrefix(n, root);
            if (remaining > count) {
                remaining -= count;
            } else {
                return select(n, root, remaining);
            }
        }
        return -1;
    }

    private int select(int n, long prefix, long remaining) {
        if (remaining == 1) {
            return (int) prefix;
        }
        remaining--;
        for (int digit = 0; digit <= 9; digit++) {
            long child = prefix * 10 + digit;
            long count = countPrefix(n, child);
            if (remaining > count) {
                remaining -= count;
            } else {
                return select(n, child, remaining);
            }
        }
        return -1;
    }

    private long countPrefix(int n, long prefix) {
        long current = prefix;
        long next = prefix + 1;
        long count = 0;
        while (current <= n) {
            count += Math.min(n + 1L, next) - current;
            current *= 10;
            next *= 10;
        }
        return count;
    }
}

class Solution {
    public int findKthNumber(int n, int k) {
        long prefix = 0;
        long remaining = k;
        while (true) {
            int start = prefix == 0 ? 1 : 0;
            for (int digit = start; digit <= 9; digit++) {
                long candidate = prefix * 10 + digit;
                long count = countPrefix(n, candidate);
                if (remaining > count) {
                    remaining -= count;
                    continue;
                }
                if (remaining == 1) {
                    return (int) candidate;
                }
                remaining--;
                prefix = candidate;
                break;
            }
        }
    }

    private long countPrefix(int n, long prefix) {
        long left = prefix;
        long right = prefix + 1;
        long total = 0;
        while (left <= n) {
            total += Math.min(n + 1L, right) - left;
            left *= 10;
            right *= 10;
        }
        return total;
    }
}

class Solution {
    public int findKthNumber(int n, int k) {
        String limit = Integer.toString(n);
        long current = 1;
        long remaining = k - 1L;
        while (remaining > 0) {
            long count = countByStringBound(limit, Long.toString(current));
            if (count <= remaining) {
                current++;
                remaining -= count;
            } else {
                current *= 10;
                remaining--;
            }
        }
        return (int) current;
    }

    private long countByStringBound(String limit, String prefix) {
        long total = 0;
        for (int length = prefix.length(); length <= limit.length(); length++) {
            String zeros = repeat('0', length - prefix.length());
            String nines = repeat('9', length - prefix.length());
            String low = prefix + zeros;
            String high = prefix + nines;
            if (length < limit.length()) {
                total += Long.parseLong(high) - Long.parseLong(low) + 1;
            } else if (low.compareTo(limit) <= 0) {
                long upper = Math.min(Long.parseLong(high), Long.parseLong(limit));
                total += upper - Long.parseLong(low) + 1;
            }
        }
        return total;
    }

    private String repeat(char ch, int count) {
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < count; i++) {
            builder.append(ch);
        }
        return builder.toString();
    }
}
